    // Small residuals (< 10) are extremely hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead (k=2):
    // If the next item is large, favor bins that leave enough space for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0;
        } else {
            // Reward bins that fit the next item perfectly (Best-Fit-Lookahead)
            score -= (post_residual - next_item_size) as f64 * 0.1;
        }
    }

    // 3. Modulo-based "Perfect Fit" incentive:
    // If we can achieve a residue of 0 or a multiple of 20, reward it.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 4. Global Load Balancing:
    // Penalize opening new bins if we have many open bins already.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // Discourage new bin if fitting options exist
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize space consolidation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Mean Residual alignment:
    // Penalize bins that deviate significantly from the mean occupancy.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
