pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best-Fit principle).
    let mut score = post;

    // Penalty for creating a "fragment": a small, unusable residual space.
    // We penalize post_residuals that are too small to fit common items (e.g., < 20).
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post).powi(2) * 0.5;
    }

    // Lookahead logic: If the next item exists, penalize bins that cannot fit it
    // but favor bins that leave enough room for it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        } else {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Adaptivity: As the stream progresses, become more aggressive in packing
    // tightly to minimize the number of open bins (lower open_bins_count is better).
    score += (open_bins_count as f64) * progress * 2.0;

    // New Bin Logic: If this is an empty bin (bin_residual == bin_capacity),
    // calculate a threshold to decide if we should force a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very high (wasted space)
        // or if we have no other efficient options.
        score = mean_residual * 0.8 + (1.0 - progress) * 10.0;

        // If we are at the beginning of the stream, be more conservative with new bins.
        if progress < 0.1 {
            score += 50.0;
        }
    }

    // If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

