    // boost its priority to keep the variance of residuals low.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.5;
    }

    // Scarcity constraint: If this is the only bin that fits the item (fitting_bins_count == 1),
