pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize creating "dead space" (small residuals that are hard to fill)
    // Residuals between 1 and 9 are often impossible to fill given the input range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead logic: If the next item can fit in the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Global state: If we are near the end of the stream, favor tighter packing (Best Fit).
    // If we are early, favor leaving bins open that have high residuals.
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // 4. Critical decision: When to open a new bin.
    // If this is a new bin, penalize it heavily unless we are forced or the fit is perfect.
    if is_new_bin {
        // High penalty for opening a new bin if other bins can fit the item
        score += 65.0;

        // If the item is large (e.g., > 70), opening a new bin is less penalized
        if item_size > 70 {
            score -= 20.0;
        }

        // If we have very few open bins, opening a new one is okay
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // Reward filling bins that are already partially filled
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // 5. If this is the last chance for this item, prioritize it to avoid opening a new bin later.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the residual space after placement
    let mut score = post_residual as f64;

    // 1. Penalty for creating "unusable" small gaps (dead space)
    // Gaps between 1 and 9 are extremely difficult to fill given item range 10-100.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead optimization (Best Fit / Next Fit hybrid)
    // If next_item_size exists, penalize bins that cannot fit it after current placement
    if next_item_size > 0 && post_residual < next_item_size {
        score += 150.0;
    }

    // 3. Pressure management
    // As we approach the end of the stream, prioritize closing bins to reduce total count
    // If this is a new bin, apply a progress-dependent penalty
    if bin_residual == bin_capacity {
        score += 80.0 + (progress * 40.0);
    } else {
        // If it's an existing bin, reward it based on how well it balances residual space
        // compared to the mean of all open bins
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // 4. Critical thresholding
    // If this is the only bin that can fit the item, strongly prioritize it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 5. Penalize excessive open bin count to encourage density
    score += (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that cannot fit common small items (e.g., < 20).
    // If post_residual is in the "danger zone" (1..19), we heavily penalize it.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Heuristic: If this is the only bin that can fit the item, prioritize it to avoid new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Harmonic class logic: Favor bins that leave a residual which is a multiple of 25 (e.g., 0, 25, 50).
    // This encourages packing items to leave "clean" space for future large items.
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // If considering a new bin, penalize based on how much space is left in existing open bins.
    // Opening a new bin is expensive unless existing bins are extremely crowded.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Penalty for opening a new bin if the mean residual of existing bins is high.
            score += mean_residual * 0.5;
        }
    }

    // Progression scaling: As we approach the end of the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalty for leaving "dead space" that is too small for common items (e.g., < 10)
    // We penalize smaller residuals more aggressively as the stream progresses to consolidate packing.
    if post_residual < 10 && post_residual > 0 {
        score += (10.0 - post_res) * (1.0 + 2.0 * progress);
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than the next item, we penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Heuristic for new bin creation:
    // If the bin is new (bin_residual == bin_capacity), only pick it if packing the item 
    // into existing bins leads to poor utilization (high mean_residual).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless the existing bins are already very full.
        // As progress increases, we become more conservative about opening new bins.
        score = 80.0 + (mean_residual * 0.5) + (progress * 40.0);
    } else {
        // Reward bins that bring the residual closer to the global mean,
        // effectively balancing the load across all open bins.
        let deviation = (post_res - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bin overhead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}
